/**
 * Unit tests for AbstractIntegrator.acceptStep.
 * Since acceptStep is protected, we use a Test subclass to expose it.
 */
public class AbstractIntegrator_acceptStep_TriageGen0Test {

    private TestIntegrator integrator;
    private AbstractStepInterpolator mockInterpolator;
    private double[] y;
    private double[] yDot;
    private final double tEnd = 10.0;

    // Subclass to expose protected method and allow overriding computeDerivatives
    private static class TestIntegrator extends AbstractIntegrator {
        private boolean statesInitialized = false;
        private boolean resetOccurred = false;
        private boolean isLastStep = false;
        private List<EventState> eventsStates = new ArrayList<>();
        private List<StepHandler> stepHandlers = new ArrayList<>();

        protected TestIntegrator() {
            super("TestIntegrator");
        }

        @Override
        public void computeDerivatives(final double t, final double[] y, final double[] yDot) {
            // Mock implementation
            yDot[0] = 1.0;
        }

        @Override
        protected void setStateInitialized(final boolean stateInitialized) {
            this.statesInitialized = stateInitialized;
        }

        // Helper to allow test to set internal state
        public void setStatesInitialized(boolean val) { this.statesInitialized = val; }
        public void setEventsStates(List<EventState> states) { this.eventsStates = states; }
        public void setStepHandlers(List<StepHandler> handlers) { this.stepHandlers = handlers; }
        public void setIsLastStep(boolean val) { this.isLastStep = val; }
        public void setResetOccurred(boolean val) { this.resetOccurred = val; }

        @Override
        protected double acceptStep(final AbstractStepInterpolator interpolator,
                                    final double[] y, final double[] yDot, final double tEnd)
                throws MaxCountExceededException, DimensionMismatchException, NoBracketingException {
            return super.acceptStep(interpolator, y, yDot, tEnd);
        }
    }

    @Before
    public void setUp() {
        integrator = new TestIntegrator();
        mockInterpolator = mock(AbstractStepInterpolator.class);
        y = new double[]{1.0, 2.0};
        yDot = new double[]{0.0, 0.0};

        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(0.0);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(5.0);
        when(mockInterpolator.isForward()).thenReturn(true);
        when(mockInterpolator.getInterpolatedState()).thenReturn(new double[]{1.5, 2.5});
    }

    @Test
    public void testAcceptStep_NoEvents() throws Exception {
        integrator.setStatesInitialized(true);
        integrator.setEventsStates(new ArrayList<>());

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, tEnd);

        assertEquals(5.0, resultT, 1e-10);
        verify(mockInterpolator).setInterpolatedTime(5.0);
    }

    @Test
    public void testAcceptStep_Initialization() throws Exception {
        integrator.setStatesInitialized(false);
        EventState mockState = mock(EventState.class);
        integrator.setEventsStates(List.of(mockState));

        integrator.acceptStep(mockInterpolator, y, yDot, tEnd);

        verify(mockState).reinitializeBegin(mockInterpolator);
    }

    @Test
    public void testAcceptStep_EventTriggersStop() throws Exception {
        integrator.setStatesInitialized(true);
        EventState event = mock(EventState.class);
        when(event.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event.getEventTime()).thenReturn(2.0);
        when(event.stop()).thenReturn(true);

        integrator.setEventsStates(List.of(event));

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, tEnd);

        assertEquals(2.0, resultT, 1e-10);
        verify(mockInterpolator).setSoftCurrentTime(2.0);
    }

    @Test
    public void testAcceptStep_EventTriggersReset() throws Exception {
        integrator.setStatesInitialized(true);
        EventState event = mock(EventState.class);
        when(event.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event.getEventTime()).thenReturn(2.0);
        when(event.stop()).thenReturn(false);
        when(event.reset(anyDouble(), any(double[].class))).thenReturn(true);

        integrator.setEventsStates(List.of(event));

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, tEnd);

        assertEquals(2.0, resultT, 1e-10);
        assertEquals(1.5, y[0], 1e-10); // eventY[0] was 1.5 from mockInterpolator
    }

    @Test
    public void testAcceptStep_MultipleEvents_ChronologicalOrder() throws Exception {
        integrator.setStatesInitialized(true);

        EventState event1 = mock(EventState.class);
        when(event1.getEventTime()).thenReturn(4.0);
        when(event1.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event1.stop()).thenReturn(false);
        when(event1.reset(anyDouble(), any(double[].class))).thenReturn(false);
        // Re-evaluate to false so it doesn't loop infinitely in this test
        when(event1.evaluateStep(mockInterpolator)).thenReturn(true).thenReturn(false);

        EventState event2 = mock(EventState.class);
        when(event2.getEventTime()).thenReturn(2.0);
        when(event2.evaluateStep(mockInterpolator)).thenReturn(true);
        when(event2.stop()).thenReturn(false);
        when(event2.reset(anyDouble(), any(double[].class))).thenReturn(false);
        when(event2.evaluateStep(mockInterpolator)).thenReturn(true).thenReturn(false);

        integrator.setEventsStates(new ArrayList<>(List.of(event1, event2)));

        // Should process event2 (time 2.0) then event1 (time 4.0)
        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, tEnd);

        assertEquals(5.0, resultT, 1e-10); 
        verify(mockInterpolator).setSoftCurrentTime(2.0);
        verify(mockInterpolator).setSoftCurrentTime(4.0);
    }

    @Test
    public void testAcceptStep_StepHandlerExecution() throws Exception {
        integrator.setStatesInitialized(true);
        StepHandler handler = mock(StepHandler.class);
        integrator.setStepHandlers(List.of(handler));

        // Case 1: No events, triggers handler at end
        integrator.acceptStep(mockInterpolator, y, yDot, tEnd);
        verify(handler).handleStep(eq(mockInterpolator), anyBoolean());
    }

    @Test
    public void testAcceptStep_PrecisionEqualsTEnd() throws Exception {
        integrator.setStatesInitialized(true);
        integrator.setEventsStates(new ArrayList<>());

        // Set currentT to exactly tEnd
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(10.0);

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, 10.0);

        assertEquals(10.0, resultT, 1e-10);
    }

    @Test
    public void testAcceptStep_ReverseIntegration() throws Exception {
        integrator.setStatesInitialized(true);
        integrator.setEventsStates(new ArrayList<>());

        // Test orderingSign logic by making isForward false
        when(mockInterpolator.isForward()).thenReturn(false);
        when(mockInterpolator.getGlobalCurrentTime()).thenReturn(5.0);
        when(mockInterpolator.getGlobalPreviousTime()).thenReturn(10.0);

        double resultT = integrator.acceptStep(mockInterpolator, y, yDot, tEnd);
        assertEquals(5.0, resultT, 1e-10);
    }
}
